syntax:
object Shell {
  object System extends Shell {
    def run(cmd: List[String]): Either[String, String] = scala.util.Try {
      val p = new ProcessBuilder(cmd.asJava).redirectErrorStream(false).start()
      val out = new String(p.getInputStream.readAllBytes, "UTF-8")
      val err = new String(p.getErrorStream.readAllBytes, "UTF-8")
      val rc = p.waitFor()
      if (rc == 0) Right(out) else Left(s"${
        cmd.head
      } exited $rc: ${
        err.trim.take(400)
      }")
    }.fold(e => Left(s"${
      cmd.headOption.getOrElse("command")
    } could not be run: ${
      e.getMessage
    }"), identity)
    def isRunning(processMatch: String): Boolean = run(List("pgrep", "-f", processMatch)).exists(_.trim.nonEmpty)
  }
}

object System extends Shell {
  def run(cmd: List[String]): Either[String, String] = scala.util.Try {
    val p = new ProcessBuilder(cmd.asJava).redirectErrorStream(false).start()
    val out = new String(p.getInputStream.readAllBytes, "UTF-8")
    val err = new String(p.getErrorStream.readAllBytes, "UTF-8")
    val rc = p.waitFor()
    if (rc == 0) Right(out) else Left(s"${
      cmd.head
    } exited $rc: ${
      err.trim.take(400)
    }")
  }.fold(e => Left(s"${
    cmd.headOption.getOrElse("command")
  } could not be run: ${
    e.getMessage
  }"), identity)
  def isRunning(processMatch: String): Boolean = run(List("pgrep", "-f", processMatch)).exists(_.trim.nonEmpty)
}

